set -eu
target=/srv/legacy2/large-counter-overflow/bin/total.py
tmp_file=$(mktemp /srv/legacy2/large-counter-overflow/bin/.total.py.XXXXXX)
trap 'rm -f "$tmp_file"' EXIT HUP INT TERM
cat >"$tmp_file" <<'ANTRIEB_TOTAL_EOF'
#!/usr/bin/python3
import re
import sys

DECIMAL_COUNTER = re.compile(r"^[0-9]+$")


def report_error(message):
    sys.stderr.write("total.py: {0}\n".format(message))
    return 1


def main(argv):
    if len(argv) != 2:
        return report_error("usage: total.py COUNTER_FILE")

    # Python integers are arbitrary precision. Disable Python's optional
    # decimal conversion length guard so valid counters remain exact.
    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)

    total = 0
    try:
        with open(argv[1], "r", encoding="ascii") as counter_file:
            for line_number, line in enumerate(counter_file, 1):
                record = line.strip()
                if DECIMAL_COUNTER.match(record) is None:
                    return report_error(
                        "invalid nonnegative decimal counter at line {0}".format(
                            line_number
                        )
                    )
                total += int(record, 10)
    except (OSError, UnicodeError) as exc:
        return report_error(str(exc))

    # Output happens only after every record has been validated.
    sys.stdout.write(str(total) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
ANTRIEB_TOTAL_EOF
chmod 0755 "$tmp_file"
